ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS owner_user_id uuid, ADD COLUMN IF NOT EXISTS invoice_number text;
ALTER TABLE public.tickets ADD COLUMN IF NOT EXISTS holder_user_id uuid;
UPDATE public.orders o SET owner_user_id=u.id FROM auth.users u WHERE o.owner_user_id IS NULL AND u.email_confirmed_at IS NOT NULL AND lower(o.email)=lower(u.email);
UPDATE public.tickets t SET holder_user_id=u.id FROM auth.users u WHERE t.holder_user_id IS NULL AND u.email_confirmed_at IS NOT NULL AND lower(t.holder_email)=lower(u.email);
CREATE OR REPLACE FUNCTION public.bind_verified_order_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT id INTO NEW.owner_user_id FROM auth.users WHERE email_confirmed_at IS NOT NULL AND lower(email)=lower(NEW.email) LIMIT 1; RETURN NEW; END; $$;
CREATE TRIGGER bind_verified_order_owner BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.bind_verified_order_owner();
CREATE OR REPLACE FUNCTION public.bind_verified_ticket_holder() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT id INTO NEW.holder_user_id FROM auth.users WHERE email_confirmed_at IS NOT NULL AND lower(email)=lower(NEW.holder_email) LIMIT 1; RETURN NEW; END; $$;
CREATE TRIGGER bind_verified_ticket_holder BEFORE INSERT OR UPDATE OF holder_email ON public.tickets FOR EACH ROW EXECUTE FUNCTION public.bind_verified_ticket_holder();
CREATE OR REPLACE FUNCTION public.claim_customer_orders() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); verified_email text; BEGIN SELECT email INTO verified_email FROM auth.users WHERE id=uid AND email_confirmed_at IS NOT NULL; IF verified_email IS NULL THEN RAISE EXCEPTION 'Nicht autorisiert.'; END IF; UPDATE public.orders SET owner_user_id=uid WHERE owner_user_id IS NULL AND lower(email)=lower(verified_email); UPDATE public.tickets SET holder_user_id=uid WHERE holder_user_id IS NULL AND lower(holder_email)=lower(verified_email); END; $$;
REVOKE ALL ON FUNCTION public.claim_customer_orders() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_customer_orders() TO authenticated;
DROP POLICY "Customers view own orders" ON public.orders;
CREATE POLICY "Customers view own orders" ON public.orders FOR SELECT TO authenticated USING(owner_user_id=(select auth.uid()));
DROP POLICY "Customers view own tickets" ON public.tickets;
CREATE POLICY "Customers view own tickets" ON public.tickets FOR SELECT TO authenticated USING(holder_user_id=(select auth.uid()));
DROP POLICY "Series managers can view tickets of their series" ON public.tickets;
DROP POLICY "Scanners can update ticket status" ON public.tickets;
CREATE OR REPLACE FUNCTION public.series_ticket_counts(p_series uuid) RETURNS TABLE(event_id uuid,ticket_category_id uuid,sold bigint,checked_in bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.manages_series(auth.uid(),p_series)) THEN RAISE EXCEPTION 'Nicht autorisiert.' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT t.event_id,t.ticket_category_id,count(*) FILTER(WHERE t.status IN ('valid','checked_in')),count(*) FILTER(WHERE t.status='checked_in') FROM public.tickets t JOIN public.events e ON e.id=t.event_id WHERE e.series_id=p_series GROUP BY t.event_id,t.ticket_category_id; END; $$;
REVOKE ALL ON FUNCTION public.series_ticket_counts(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.series_ticket_counts(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.transfer_owned_ticket(p_ticket uuid,p_email text,p_name text,p_message text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tickets; uid uuid:=auth.uid(); sender_email text; BEGIN
 SELECT email INTO sender_email FROM auth.users WHERE id=uid AND email_confirmed_at IS NOT NULL;
 IF sender_email IS NULL OR p_email IS NULL OR length(p_email)>255 OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(COALESCE(p_name,''))>255 OR length(COALESCE(p_message,''))>2000 OR lower(trim(p_email))=lower(sender_email) THEN RAISE EXCEPTION 'Ungültige Übertragung.'; END IF;
 SELECT * INTO t FROM public.tickets WHERE id=p_ticket FOR UPDATE;
 IF NOT FOUND OR t.holder_user_id IS DISTINCT FROM uid OR t.status<>'valid' OR NOT EXISTS(SELECT 1 FROM public.orders WHERE id=t.order_id AND status='paid') OR EXISTS(SELECT 1 FROM public.events WHERE id=t.event_id AND date<(now() AT TIME ZONE 'Europe/Berlin')::date) THEN RAISE EXCEPTION 'Ticket kann nicht übertragen werden.'; END IF;
 UPDATE public.tickets SET holder_email=lower(trim(p_email)),holder_name=p_name WHERE id=t.id;
 INSERT INTO public.ticket_transfers(ticket_id,from_user_id,from_email,to_email,to_name,message,status,completed_at) VALUES(t.id,uid,sender_email,lower(trim(p_email)),p_name,p_message,'accepted',now());
 RETURN jsonb_build_object('ok',true);
 END; $$;
REVOKE ALL ON FUNCTION public.transfer_owned_ticket(uuid,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.transfer_owned_ticket(uuid,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.allocate_order_invoice(p_order uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; cfg jsonb; num int; result text; BEGIN SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE; IF NOT FOUND OR o.status<>'paid' THEN RAISE EXCEPTION 'Bezahlte Bestellung erforderlich.'; END IF; IF o.invoice_number IS NOT NULL THEN RETURN o.invoice_number; END IF; SELECT value INTO cfg FROM public.settings WHERE key='invoice' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Rechnungskonfiguration fehlt.'; END IF; num:=GREATEST(1,COALESCE((cfg->>'next_number')::int,1)); result:=COALESCE(cfg->>'prefix','RE')||'-'||extract(year FROM now())::text||'-'||lpad(num::text,4,'0'); UPDATE public.settings SET value=jsonb_set(cfg,'{next_number}',to_jsonb(num+1)),updated_at=now() WHERE key='invoice'; UPDATE public.orders SET invoice_number=result WHERE id=o.id; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.allocate_order_invoice(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.allocate_order_invoice(uuid) TO service_role;
CREATE INDEX IF NOT EXISTS orders_owner_user_idx ON public.orders(owner_user_id);
CREATE INDEX IF NOT EXISTS tickets_holder_user_idx ON public.tickets(holder_user_id);
COMMENT ON COLUMN public.orders.owner_user_id IS 'Verified account ownership; historical email retained for audit.';
COMMENT ON COLUMN public.u18_forms.access_token_hash IS 'Hash only; document capability stays in submitting browser memory.';